# owner: platform
import unittest

from hourglass.rounding import (
    check_step,
    round_labels,
    round_minutes,
    round_span,
    span_label
)
from hourglass.models import Span


class StepTests(unittest.TestCase):
    def test_divisors_of_an_hour_pass(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                check_step(step)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    check_step(step)


class RoundMinutesTests(unittest.TestCase):
    def test_moves_to_nearest_step(self):
        self.assertEqual(round_minutes(512, 15), 510)
        self.assertEqual(round_minutes(518, 15), 525)

    def test_exact_half_goes_up(self):
        self.assertEqual(round_minutes(5, 10), 10)
        self.assertEqual(round_minutes(4, 10), 0)

    def test_step_of_one_changes_nothing(self):
        self.assertEqual(round_minutes(537, 1), 537)

    def test_bad_step_raises(self):
        with self.assertRaises(ValueError):
            round_minutes(60, 0)


class RoundSpanTests(unittest.TestCase):
    def test_both_ends_snapped(self):
        result = round_span(Span(537, 1036), 15)
        self.assertEqual(result, Span(540, 1035))

    def test_end_of_day_is_allowed(self):
        result = round_span(Span(1430, 1437), 15)
        self.assertEqual(result, Span(1425, 1440))

    def test_span_that_collapses_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)


class LabelTests(unittest.TestCase):
    def test_shows_hours_and_minutes(self):
        label = span_label(Span(540, 1035))
        self.assertEqual(label, "09:00-17:15 (8h 15m)")

    def test_whole_hours(self):
        label = span_label(Span(0, 60))
        self.assertEqual(label, "00:00-01:00 (1h 0m)")


class RoundLabelsTests(unittest.TestCase):
    def test_one_label_per_span(self):
        spans = [Span(537, 1036), Span(60, 120)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "01:00-02:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(60, 120)], step)
